from abc import ABCMeta, abstractmethod
import logging
import time
import signal
from taf.internal.managedobject import ManagedObject
from taf.collectors.core.util.super_user import sudo_prefix_required

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class TimeoutError(Exception):
    """
    A timeout has occurred.
    """

    def __init__(self, *args, timeout=None):
        super().__init__(*args)
        self.timeout = timeout

    def __str__(self):
        args = ", ".join(repr(a) for a in self.args) + ", " if self.args else ""
        return f"{args}timeout={self.timeout!r}"

    def __repr__(self):
        return f"TimeoutError({self})"


class ProcessTimeoutError(TimeoutError):
    """
    A timeout has occurred during process execution.
    """

    def __init__(self, *args, command, **kwargs):
        super().__init__(*args, **kwargs)
        self.command = command

    def __str__(self):
        return f"{super().__str__()}, command={self.command!r}"

    def __repr__(self):
        return f"ProcessTimeoutError({self})"


class ProcessTimeoutErrorWithData(ProcessTimeoutError):
    """
    A timeout has occurred during process execution, data was read so far.
    """

    def __init__(self, *args, stdout_data, stderr_data, **kwargs):
        super().__init__(*args, **kwargs)
        self.stdout_data = stdout_data
        self.stderr_data = stderr_data

    def __str__(self):
        return f"{super().__str__()}, stdout_data={self.stdout_data!r}, stderr_data={self.stderr_data!r}"

    def __repr__(self):
        return f"ProcessTimeoutErrorWithData({self})"


class ExecutorTimeoutError(TimeoutError):
    """
    A timeout has occurred during executor execution.
    """

    def __init__(self, *args, process, **kwargs):
        super().__init__(*args, **kwargs)
        self.process = process

    def __str__(self):
        return f"{super().__str__()}, process={self.process!r}"

    def __repr__(self):
        return f"ExecutorTimeoutError({self})"


class StreamTimeoutError(TimeoutError):
    """
    A timeout has occurred during stream read.
    """

    def __repr__(self):
        return f"StreamTimeoutError({self})"


class StreamTimeoutErrorWithData(StreamTimeoutError):
    """
    A timeout has occurred during stream read, data was read so far.
    """

    def __init__(self, *args, data, **kwargs):
        super().__init__(*args, **kwargs)
        self.data = data

    def __str__(self):
        return f"{super().__str__()}, data={self.data!r}"

    def __repr__(self):
        return f"StreamTimeoutErrorWithData({self})"


TimeoutErrorWithData = StreamTimeoutErrorWithData


class ExecutionError(Exception):
    """
    An execution failed.
    """

    def __init__(self, stdout, stderr, exit_status, **kwargs):
        super(ExecutionError, self).__init__(**kwargs)
        self.stdout = stdout
        self.stderr = stderr
        self.exit_status = exit_status

    def __str__(self):
        return f"stdout={self.stdout!r}, stderr={self.stderr!r}, exit_status={self.exit_status!r}"

    def __repr__(self):
        return f"ExecutionError({self})"


class TimeoutManagement(object):

    def __init__(self, **kwargs):
        super(TimeoutManagement, self).__init__(**kwargs)
        self._start_time = None

    def _set_start_time(self):
        self._start_time = self._get_current_time()

    def _get_current_time(self):
        return time.time()

    def _get_elapsed_time(self):
        return self._get_current_time() - self._start_time

    def _get_remaining_timeout(self, timeout):
        if timeout is None:
            return None
        return max(0, timeout - self._get_elapsed_time())

    def _is_timeout_exceeded(self, timeout):
        if timeout is None:
            return False
        return self._get_elapsed_time() >= timeout

    def _sleep(self, seconds):
        time.sleep(seconds)


class Executor(ManagedObject, TimeoutManagement, metaclass=ABCMeta):
    """
    Run commands.
    """

    def __init__(self, sudo_password=None, **kwargs):
        super(Executor, self).__init__(**kwargs)
        self._sudo_password = sudo_password

    @property
    def sudo_password(self):
        return self._sudo_password

    def execute(self, command, use_tty=False, timeout=None):
        """
        Execute a command and wait until it finishes.

        :param str command: command to be executed
        :param bool use_tty: if True, use a terminal when executing the command
        :param float timeout: timeout in seconds to wait for the command to finish

        :return: stdout
        :rtype: bytes
        :raise: ExecutionError, if exit status is not 0
        :raise: ExecutorTimeoutError, if process did not finish after timeout seconds
        """
        stdout, stderr, exit_status = self.raw_execute(command,
                                                       use_tty=use_tty,
                                                       timeout=timeout)
        if exit_status:
            raise ExecutionError(
                stdout=stdout,
                stderr=stderr,
                exit_status=exit_status)
        else:
            return stdout

    @abstractmethod
    def raw_execute(self, command, use_tty=False, timeout=None):
        """
        Execute a command and wait until it finishes.

        Adds logging and optionally retry to execution of command.

        :param str command: command to be executed
        :param bool use_tty: if True, use a terminal when executing the command
        :param float timeout: timeout in seconds to wait for the command to finish

        :return: stdout, stderr, exit status
        :rtype: bytes, bytes, int
        :raise: ExecutorTimeoutError, if process did not finish after timeout seconds
        """

    def _raw_execute(self, command, use_tty=False, timeout=None):
        """
        Execute a command and wait until it finishes.

        :param str command: command to be executed
        :param bool use_tty: if True, use a terminal when executing the command
        :param float timeout: timeout in seconds to wait for the command to finish

        :return: stdout, stderr, exit status
        :rtype: bytes, bytes, int
        :raise: ExecutorTimeoutError, if process did not finish after timeout seconds
        """
        self._set_start_time()
        process = self._start(
            command=command,
            use_tty=use_tty)
        try:
            stdout, stderr = process._read_output(timeout=timeout)
            process.wait(timeout=self._get_remaining_timeout(timeout))
        except ProcessTimeoutError as e:
            raise ExecutorTimeoutError(process=process, timeout=timeout) from e
        exit_status = process.exit_status
        return stdout, stderr, exit_status

    @abstractmethod
    def start(self, command, use_tty=False):
        """
        Start a command.

        Adds logging and optionally retry to start of command.

        :param str command: command to be executed
        :param bool use_tty: if True, use a terminal when executing the command

        :return: process
        :rtype: Process
        """

    @abstractmethod
    def _start(self, command, use_tty=False):
        """
        Start a command.

        :param str command: command to be executed
        :param bool use_tty: if True, use a terminal when executing the command

        :return: process
        :rtype: Process
        """

    def sudo_prefix(self):
        user = self.execute(b"whoami").decode().strip()
        logging.debug("user=%r", user)
        if sudo_prefix_required(user=user):
            sudo_prefix = ""
        elif self._sudo_password is None:
            sudo_prefix = "sudo "
        else:
            sudo_prefix = "echo '{sudo_password}' | sudo -S ".format(
                sudo_password=self._sudo_password)
        return sudo_prefix


class Process(TimeoutManagement, metaclass=ABCMeta):
    """
    Running process with input and output streams.
    """

    def __init__(self, command, stdin, stdout, stderr, **kwargs):
        super(Process, self).__init__(**kwargs)
        self._command = command
        self._stdin = stdin
        self._stdout = stdout
        self._stderr = stderr

    @property
    def stdin(self):
        return self._stdin

    @property
    def stdout(self):
        return self._stdout

    @property
    def stderr(self):
        return self._stderr

    @property
    def command(self):
        return self._command

    @abstractmethod
    def wait(self, timeout=None):
        """
        Wait until the process finishes execution.

        :param float timeout:
            wait timeout seconds for the process to finish
            (forever, if timeout is None)


        :raises: ProcessTimeoutError, if process did not finish after timeout seconds
        """

    @abstractmethod
    def _get_is_running(self):
        """
        Return True, if the process is still running.

        :return:
        """

    is_running = property(lambda self: self._get_is_running())

    @abstractmethod
    def _get_exit_status(self):
        """
        Return the exit status of a terminated process.

        :return: exit status
        :rtpye: int
        """

    exit_status = property(lambda self: self._get_exit_status())

    def terminate(self):
        """
        Terminate the process by sending SIGTERM.
        """
        self.send_signal(signal.SIGTERM)

    def kill(self):
        """
        Kill the process by sending SIGKILL.
        """
        self.send_signal(signal.SIGKILL)

    @abstractmethod
    def send_signal(self, signal):
        """
        Send a signal to the process.

        :param signal.Signals signal: signal to be sent (e.g. signal.SIGTERM, signal.SIGKILL, ...)
        """

    def read_output(self, timeout=None):
        """
        Read stdout and stderr from the process.

        Uses select() or similar techniques to avoid blocking when reading from streams.
        This method handles the problem of blocking due to > 64 kB data on either stdout
        or stderr by multiplexing between the two streams.

        :param float timeout: timeout in seconds to wait for output
        :return: stdout data, stderr data
        :rtype: bytes, bytes
        :raise: ProcessTimeoutErrorWithData, if timeout is exceeded
        """
        logger.debug("reading output from process")
        stdout, stderr = self._read_output(timeout=timeout)
        logger.debug("stdout=%r, stderr=%r", stdout, stderr)
        return stdout, stderr

    @abstractmethod
    def _read_output(self, timeout=None):
        """
        Read stdout and stderr from the process.

        This is an internal method without logging. Use read_output() for public API.

        :param float timeout: timeout in seconds to wait for output
        :return: stdout data, stderr data
        :rtype: bytes, bytes
        :raise: ProcessTimeoutErrorWithData, if timeout is exceeded
        """


class InputStream(metaclass=ABCMeta):
    """
    Input stream of a process (stdin), where input data can be written to.
    """

    @abstractmethod
    def write(self, data):
        """
        Write data to stream.

        :param bytes data: data to be written into the input stream
        """

    @abstractmethod
    def close(self):
        """
        Close the input stream.
        """


class OutputStream(TimeoutManagement, metaclass=ABCMeta):
    """
    Output stream of a process (stdout or stderr), where output data can be read from.
    """

    def read(self, size=None, timeout=None):
        """
        Read data from stream.

        :param int size: maximum number of bytes to read (read all data, if size is None)
        :param float timeout: timeout in seconds to wait for the next character

        :return: read data
        :rtype: bytes
        :raise: StreamTimeoutError, if timeout is exceeded while waiting for data
        """
        logger.debug("reading from {stream_name} with size {size!r} and timeout {timeout!r}".format(
            stream_name=self._stream_name,
            size=size,
            timeout=timeout))
        data = self._read(size, timeout)
        logger.debug("data=%r", data)
        return data

    @abstractmethod
    def _read(self, size=None, timeout=None):
        """
        Read data from stream.

        :param int size: maximum number of bytes to read (read all data, if size is None)
        :param float timeout: timeout in seconds to wait for the next character

        :return: read data
        :rtype: bytes
        """

    def read_until_string(self, string, timeout=None, prefix=None):
        """
        Read data from stream until a string occurs or EOF.

        :param bytes string: string to search for
        :param float timeout: timeout in seconds
        :param bytes prefix: partly read line from previous call, which timed out

        :return: read data
        :rtype: bytes
        """
        logger.debug("reading until string {string!r} from {stream_name}".format(
            stream_name=self._stream_name,
            string=string))
        return self._read_until_string(
            string=string,
            timeout=timeout,
            prefix=prefix)

    def _read_until_string(self, string, timeout=None, prefix=None):  # noqa: C901
        """
        Read data from stream until a string occurs or EOF.

        :param bytes string: string to search for
        :param float timeout: timeout in seconds
        :param bytes prefix: partly read line from previous call, which timed out

        :return: read data
        :rtype: bytes
        """
        self._set_start_time()
        if prefix is None:
            data = b""
        else:
            data = prefix[:]
        while True:
            try:
                if timeout is None:
                    char = self._read(size=1, timeout=timeout)
                else:
                    remaining_timeout = self._get_remaining_timeout(timeout)
                    if remaining_timeout > 0:
                        char = self._read(size=1, timeout=remaining_timeout)
                    else:
                        raise StreamTimeoutError(timeout=timeout)
                data += char
                if not char or data.endswith(string):
                    logger.debug("data=%r", data)
                    return data
            except StreamTimeoutError as e:
                logger.debug("timeout, data=%r", data)
                raise StreamTimeoutErrorWithData(timeout=timeout, data=data) from e

    def read_line(self, timeout=None, prefix=None):
        """
        Read data from stream until line end or EOF.

        :param float timeout: timeout in seconds
        :param bytes prefix: partly read line from previous call, which timed out

        :return: read data
        :rtype: bytes
        """
        logger.debug("reading line from {stream_name}".format(
            stream_name=self._stream_name))
        return self._read_until_string(
            string=b"\n",
            timeout=timeout,
            prefix=prefix)

    def __iter__(self):
        """
        Iterate over lines.

        :return: next line
        :rtype: bytes
        """
        while True:
            line = self.read_line()
            if not line:
                return
            yield line
